import React, { useEffect } from 'react';
import { Container, Typography, Box, Button } from '@material-ui/core';
import { makeStyles } from '@material-ui/core/styles';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';

const useStyles = makeStyles((theme) => ({
  root: {
    minHeight: '100vh',
    paddingTop: theme.spacing(8),
    paddingBottom: theme.spacing(8),
    textAlign: 'center',
    background: 'linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)',
    position: 'relative',
    overflow: 'hidden',
  },
  content: {
    position: 'relative',
    zIndex: 2,
  },
  title: {
    marginBottom: theme.spacing(4),
    fontWeight: 900,
    background: 'linear-gradient(45deg, #2196F3 30%, #21CBF3 90%)',
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
    textShadow: '2px 2px 4px rgba(0,0,0,0.1)',
  },
  subtitle: {
    marginBottom: theme.spacing(6),
    color: theme.palette.text.secondary,
    fontSize: '1.5rem',
    lineHeight: 1.6,
    fontWeight: 500,
  },
  loginButton: {
    marginTop: theme.spacing(4),
    padding: theme.spacing(2, 6),
    fontSize: '1.3rem',
    borderRadius: 30,
    background: 'linear-gradient(45deg, #2196F3 30%, #21CBF3 90%)',
    boxShadow: '0 3px 15px rgba(33, 203, 243, 0.3)',
    transition: 'all 0.3s ease',
    '&:hover': {
      transform: 'translateY(-3px)',
      boxShadow: '0 5px 20px rgba(33, 203, 243, 0.5)',
    },
  },
  decorCircle: {
    position: 'absolute',
    borderRadius: '50%',
    background: 'linear-gradient(45deg, #2196F3 30%, #21CBF3 90%)',
    opacity: 0.1,
  },
}));

function Home() {
  const classes = useStyles();

  useEffect(() => {
    const circles = document.querySelectorAll('.decor-circle');
    circles.forEach(circle => {
      circle.style.animation = `float ${Math.random() * 5 + 5}s ease-in-out infinite`;
    });
  }, []);

  const containerVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: {
        duration: 0.8,
        staggerChildren: 0.3
      }
    }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0
    }
  };

  return (
    <Container className={classes.root} maxWidth={false}>
      {/* Decorative circles */}
      {[...Array(5)].map((_, i) => (
        <Box
          key={i}
          className={`decor-circle ${classes.decorCircle}`}
          style={{
            width: `${Math.random() * 200 + 100}px`,
            height: `${Math.random() * 200 + 100}px`,
            left: `${Math.random() * 100}%`,
            top: `${Math.random() * 100}%`,
          }}
        />
      ))}

      <motion.div
        className={classes.content}
        initial="hidden"
        animate="visible"
        variants={containerVariants}
      >
        <Box maxWidth={800} mx="auto">
          <motion.div variants={itemVariants}>
            <Typography variant="h2" className={classes.title}>
              Welcome to Dynonary English
            </Typography>
          </motion.div>

          <motion.div variants={itemVariants}>
            <Typography variant="h5" className={classes.subtitle}>
              Your personal English learning companion. Improve your vocabulary, practice pronunciation, 
              and master the English language with our interactive tools.
            </Typography>
          </motion.div>

          <motion.div variants={itemVariants}>
            <Button
              component={Link}
              to="/login"
              variant="contained"
              color="primary"
              size="large"
              className={classes.loginButton}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              Login to Start Learning
            </Button>
          </motion.div>
        </Box>
      </motion.div>

      <style jsx>{`
        @keyframes float {
          0%, 100% { transform: translateY(0) rotate(0deg); }
          50% { transform: translateY(-20px) rotate(10deg); }
        }
      `}</style>
    </Container>
  );
}

export default Home;
